async function handleDelivery(event) {
  let approved = false;
  const session = await client.createSession({
    onPermissionRequest: requestToolPermission,
    hooks: {
      onPreToolUse: async () => approved
        ? { permissionDecision: "allow" }
        : {
            permissionDecision: {{s1}},
            permissionDecisionReason: "Planning only; approval required."
          }
    }
  });
  try {
    const plan = await session.sendAndWait({
      prompt: `Plan this webhook task without executing tools: ${JSON.stringify(event)}`
    });
    if (!plan?.data.content) return;
    approved = await requestHumanApproval(plan.data.content);
    if (!approved) return;
    await session.sendAndWait({ prompt: "Execute the approved plan in this session." });
  } finally {
    await session.disconnect();
  }
}

name: agent-guardrails
on:
  pull_request:
    branches: [main]
  pull_request_review:
    types: [submitted, dismissed]
permissions:
  contents: read
  pull-requests: read
jobs:
  block-agent-prs:
    runs-on: ubuntu-latest
    steps:
      - name: Block designated agent-authored PRs
        if: ${{ {{s1}} }}
        run: exit 1
      - name: Require a current human approval
        uses: actions/github-script@v8
        with:
          script: |
            const { owner, repo } = context.repo;
            const pr = context.payload.pull_request;
            const reviews = await github.paginate(github.rest.pulls.listReviews, {
              owner, repo, pull_number: pr.number
            });
            const latest = new Map();
            for (const review of reviews) {
              if (review.user && ["APPROVED", "CHANGES_REQUESTED", "DISMISSED"].includes(review.state)) {
                latest.set(review.user.id, review);
              }
            }
            const approvedByHuman = [...latest.values()].some(r =>
              r.state === "APPROVED" &&
              r.commit_id === pr.head.sha &&
              r.user.type === "{{s2}}" &&
              r.user.login !== "{{s3}}"
            );
            if (!approvedByHuman) core.setFailed("Human approval is required before merge.");
